INSERT INTO `campus_activity` (`title`, `description`, `category_id`, `location`, `cover`, `start_time`, `end_time`, `max_participants`, `current_participants`, `organizer`, `organizer_id`, `status`, `created_at`) VALUES
  ('校运会 5 公里欢乐跑', '一年一度的校园欢乐跑,不设成绩门槛,完赛即得纪念奖牌与第二课堂学分。路线途经图书馆、银杏大道与湖畔。', 2, '东区操场', 'https://images.pexels.com/photos/32327116/pexels-photo-32327116.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 78 HOUR), DATE_ADD(NOW(), INTERVAL 82 HOUR), 200, 156, '校团委·学生会', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 14 DAY)),
  ('周末读书会:当我们谈论校园时', '本期共读《你当像鸟飞往你的山》,由文学院老师领读。现场提供茶水,带自己的书即可参加。', 1, '图书馆一楼报告厅', 'https://images.pexels.com/photos/32751996/pexels-photo-32751996.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 147 HOUR), DATE_ADD(NOW(), INTERVAL 149 HOUR), 60, 38, '图书馆·文学院', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 20 DAY)),
  ('秋季校园二手市集', '毕业季版二手市集回归!报名成为摊主处理闲置好物,逛集的同学还能参与抽奖赢取文创周边。', 3, '学生活动中心广场', 'https://images.pexels.com/photos/19152576/pexels-photo-19152576.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 241 HOUR), DATE_ADD(NOW(), INTERVAL 247 HOUR), 150, 103, '校团委·社联', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 19 DAY)),
  ('AI 大模型入门分享会', '计算机学院学长带你从零认识大模型:原理、Prompt 技巧、本地部署实战,零基础友好。', 1, '教三 402', 'https://images.pexels.com/photos/34774347/pexels-photo-34774347.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 30 HOUR), DATE_ADD(NOW(), INTERVAL 36 HOUR), 80, 66, '计算机学院科协', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 16 DAY)),
  ('新生破冰定向越野', '分组完成校园地标打卡任务,赢积分换礼品。认识新朋友的第一站,欢迎所有年级参加。', 4, '校园全域', 'https://images.pexels.com/photos/4314209/pexels-photo-4314209.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 336 HOUR), DATE_ADD(NOW(), INTERVAL 343 HOUR), 120, 66, '校学生会', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 18 DAY)),
  ('校园摄影展作品征集', '以「我眼里的四季校园」为主题征集摄影作品,入选作品将在图书馆走廊展出并收录进校园年鉴。', 5, '线上投稿+图书馆展出', 'https://images.pexels.com/photos/5466870/pexels-photo-5466870.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 101 HOUR), DATE_ADD(NOW(), INTERVAL 109 HOUR), 100, 47, '摄影协会', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 7 DAY)),
  ('编程马拉松 HackNight 36h', '36 小时极限开发,主题现场揭晓。提供场地、夜宵与导师辅导,优秀团队直通校级竞赛。', 6, '创新创业学院 3F', 'https://images.pexels.com/photos/8128190/pexels-photo-8128190.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 485 HOUR), DATE_ADD(NOW(), INTERVAL 487 HOUR), 60, 41, '创新创业学院', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 19 DAY)),
  ('吉他社草地音乐节', '夏夜草坪音乐会,社团乐队与个人弹唱轮番登场,观众可自由点歌,现场提供荧光棒。', 5, '湖畔草坪', 'https://images.pexels.com/photos/16803238/pexels-photo-16803238.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 151 HOUR), DATE_ADD(NOW(), INTERVAL 159 HOUR), 300, 212, '吉他社', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 9 DAY)),
  ('考研经验分享会(上岸学长学姐团)', '数学、英语、专业课三场分论坛并行,上岸学长学姐面对面答疑,会后资料包分享。', 1, '行政楼 201', 'https://images.pexels.com/photos/37811241/pexels-photo-37811241.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL -215 HOUR), DATE_ADD(NOW(), INTERVAL -212 HOUR), 200, 200, '校团委·学习部', 1, 'FINISHED', DATE_SUB(NOW(), INTERVAL 21 DAY)),
  ('校园公益旧衣回收', '与市慈善总会合作的旧衣回收活动,每回收 1kg 将配捐 1 元至山区图书角项目。', 4, '各宿舍楼下', 'https://images.pexels.com/photos/6994940/pexels-photo-6994940.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL -41 HOUR), DATE_ADD(NOW(), INTERVAL -37 HOUR), 500, 318, '青年志愿者协会', 1, 'FINISHED', DATE_SUB(NOW(), INTERVAL 13 DAY)),
  ('校辩论队表演赛:人工智能应否进入课堂', '正反双方各 20 分钟立论与质询,现场观众可参与自由辩论环节。', 1, '学生活动中心报告厅', 'https://images.pexels.com/photos/17558082/pexels-photo-17558082.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL -19 HOUR), DATE_ADD(NOW(), INTERVAL -11 HOUR), 260, 260, '校辩论队', 1, 'FINISHED', DATE_SUB(NOW(), INTERVAL 7 DAY)),
  ('新生杯篮球联赛揭幕战', '十二支学院队伍抽签对阵,揭幕战由计算机学院对阵经济学院,欢迎到场助威。', 2, '东区体育馆', 'https://images.pexels.com/photos/32600343/pexels-photo-32600343.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 52 HOUR), DATE_ADD(NOW(), INTERVAL 58 HOUR), 400, 122, '体育部', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 14 DAY)),
  ('英语角:Travel Around the World', '外教主持,每期一个国家主题,本期聊聊东南亚背包旅行。口语薄弱也能大胆开口。', 1, '外语楼 301', 'https://images.pexels.com/photos/7972561/pexels-photo-7972561.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 120 HOUR), DATE_ADD(NOW(), INTERVAL 124 HOUR), 50, 31, '外国语学院', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 12 DAY)),
  ('手作工作坊:皮革卡包 DIY', '两小时做出自己的卡包,材料费 15 元,成品带走。限 30 人,手慢无。', 3, '创新创业学院 1F', 'https://images.pexels.com/photos/4452508/pexels-photo-4452508.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 194 HOUR), DATE_ADD(NOW(), INTERVAL 200 HOUR), 30, 19, '手作社', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 10 DAY)),
  ('校园歌手大赛海选', '一年一度的校园歌手大赛开始报名!海选清唱 90 秒,晋级即进复赛。', 5, '学生活动中心 K 吧', 'https://images.pexels.com/photos/16108227/pexels-photo-16108227.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 294 HOUR), DATE_ADD(NOW(), INTERVAL 299 HOUR), 150, 88, '学生会文艺部', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 11 DAY)),
  ('急救知识培训(CPR+AED)', '红十字会认证讲师授课,通过考核可获急救员证书,适合有支教和志愿计划的同学。', 4, '校医院 3 楼教室', 'https://images.pexels.com/photos/33317471/pexels-photo-33317471.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 385 HOUR), DATE_ADD(NOW(), INTERVAL 392 HOUR), 40, 28, '红十字协会', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 11 DAY)),
  ('秋日定向越野挑战赛', '双人组队,山地+公园混合赛道,完赛率最高的前三组有奖。', 2, '西区山地公园', 'https://images.pexels.com/photos/14137287/pexels-photo-14137287.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 528 HOUR), DATE_ADD(NOW(), INTERVAL 535 HOUR), 90, 52, '户外运动协会', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 17 DAY)),
  ('职业生涯规划讲座:简历与面试', '资深 HR 现场改简历,模拟面试环节,应届生必听。', 1, '就业指导中心 210', 'https://images.pexels.com/photos/8761330/pexels-photo-8761330.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 628 HOUR), DATE_ADD(NOW(), INTERVAL 634 HOUR), 120, 74, '就业指导中心', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 11 DAY)),
  ('汉服游园会', '汉服走秀+传统游戏+手工集市,穿汉服入场可领纪念书签。', 5, '中心花园', 'https://images.pexels.com/photos/37664482/pexels-photo-37664482.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 723 HOUR), DATE_ADD(NOW(), INTERVAL 729 HOUR), 200, 135, '汉服社', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 10 DAY)),
  ('深夜自习室打卡挑战', '连续 7 天晚 10 点后打卡满 5 次即可获得图书馆文创奖品,一起卷起来。', 6, '图书馆 24 小时自习区', 'https://images.pexels.com/photos/9572540/pexels-photo-9572540.jpeg?auto=compress&cs=tinysrgb&w=800', DATE_ADD(NOW(), INTERVAL 6 HOUR), DATE_ADD(NOW(), INTERVAL 11 HOUR), 300, 96, '图书馆', 1, 'UPCOMING', DATE_SUB(NOW(), INTERVAL 9 DAY));

